<template><div class="page"><v-card flat class="pa-5 mb-4 hero"><div class="d-flex align-center"><div><div class="text-overline">SALES CRM</div><h1 class="text-h5 font-weight-bold">Site Visits</h1><div class="grey--text">Schedule and monitor property visits.</div></div><v-spacer/><v-btn color="#165134" dark @click="open"><v-icon left>mdi-calendar-plus</v-icon>Schedule Visit</v-btn></div></v-card><v-card flat><v-data-table :headers="headers" :items="items" :loading="loading"><template v-slot:item.status="{item}"><v-chip x-small>{{item.status}}</v-chip></template><template v-slot:item.visit_at="{item}">{{item.visit_at}}</template></v-data-table></v-card><v-dialog v-model="dialog" max-width="600"><v-card><v-card-title>Schedule Site Visit</v-card-title><v-card-text><v-row><v-col cols="12" md="6"><v-text-field v-model="form.customer_id" outlined dense type="number" label="Customer ID"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.lead_id" outlined dense type="number" label="Lead ID"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.property_id" outlined dense type="number" label="Property ID"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.visit_at" outlined dense type="datetime-local" label="Visit Date & Time *"/></v-col><v-col cols="12" md="6"><v-select v-model="form.status" :items="['scheduled','completed','cancelled','no_show']" outlined dense label="Status"/></v-col><v-col cols="12"><v-textarea v-model="form.notes" outlined dense label="Notes"/></v-col></v-row></v-card-text><v-card-actions><v-spacer/><v-btn text @click="dialog=false">Cancel</v-btn><v-btn color="#165134" dark :loading="saving" @click="save">Schedule</v-btn></v-card-actions></v-card></v-dialog></div></template><script>import api from '../../../services/api';export default{name:'SiteVisits',data(){return{loading:false,saving:false,dialog:false,items:[],headers:[{text:'Customer',value:'customer.name'},{text:'Property',value:'property.property_number'},{text:'Visit',value:'visit_at'},{text:'Status',value:'status'},{text:'Notes',value:'notes'}],form:{customer_id:null,lead_id:null,property_id:null,visit_at:'',status:'scheduled',notes:''}}},mounted(){this.load()},methods:{async load(){this.loading=true;try{const r=await api.get('/site-visits',{params:{per_page:100}});this.items=r.data.data||[]}finally{this.loading=false}},open(){this.form={customer_id:null,lead_id:null,property_id:null,visit_at:'',status:'scheduled',notes:''};this.dialog=true},async save(){this.saving=true;try{await api.post('/site-visits',this.form);this.dialog=false;await this.load()}catch(e){this.$root.$emit('show-error',e.response?.data?.message||'Unable to schedule visit.')}finally{this.saving=false}}}}</script><style scoped>.page{width:100%}.hero{border-left:4px solid #165134}</style>